{
  "a_sentences": [
    {
      "a_text": "Der Streit dreht sich um die rückwirkende Aufhebung der Hilflosenentschädigung für Minderjährige ab 1. März 2023 und die Rückerstattungspflicht ab diesem Datum (P1).",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Nach Art. 88bis Abs. 2 lit. a RAI entfaltet die Herabsetzung oder Aufhebung einer Hilflosenentschädigung frühestens am ersten Tag des zweiten Monats nach Zustellung der Verfügung Wirkung (P2).",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Art. 88bis Abs. 2 lit. b RAI erlaubt eine rückwirkende Herabsetzung oder Aufhebung, wenn die Leistung unrechtmässig bezogen wurde oder die versicherte Person ihre Meldepflicht verletzt hat (P3).",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Die Meldepflicht nach Art. 77 RAI und Art. 31 ATSG verlangt, dass die versicherte Person der IV-Stelle jede wesentliche Änderung mitteilt, die den Leistungsanspruch beeinflussen kann (P4).",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Seit 1. Januar 2015 ist kein Kausalzusammenhang zwischen der Meldepflichtverletzung und dem unrechtmässigen Leistungsbezug mehr erforderlich, um eine rückwirkende Korrektur zu rechtfertigen (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Die Vorinstanz hielt fest, die Eltern des Versicherten hätten ihre Meldepflicht verletzt, weshalb die Hilflosenentschädigung zu Recht rückwirkend per 1. März 2023 aufgehoben und zurückgefordert wurde (P6).",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Das Bundesgericht prüft, ab welchem Zeitpunkt die Hilflosenentschädigung des Versicherten zu entziehen ist (P7).",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Das Bundesgericht verneint eine schuldhafte Meldepflichtverletzung der Eltern, weil die medizinische Situation des Versicherten instabil war und die Eltern als Laien die Tragweite der Veränderungen nicht ohne Weiteres hätten einschätzen können.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Das Bundesgericht hebt die rückwirkende Aufhebung auf und ordnet an, die Hilflosenentschädigung erst ab dem ersten Tag des zweiten Monats nach Zustellung der Verfügung vom 27. Mai 2024, also per 1. Juli 2024, zu entziehen.",
      "b_propositions": ["P7"]
    }
  ]
}
